// Learn, AMC Geometry, chapter S5: circles (CONVENTIONS §14). Part: Core topics.
// Chord geometry, arc choices, signed power and circle tangencies, with explicit configurations.
window.MATH_LEARN = window.MATH_LEARN || {};
